/**
 * ZyniVerse config plugin — Play-ready release settings.
 *
 * The `android/` folder is gitignored and is regenerated by `expo prebuild`, so
 * anything set by hand in `android/app/build.gradle` disappears on the next
 * prebuild. This plugin re-applies the two settings Play requires:
 *
 *  1. `targetSdkVersion = 35` — Google Play rejects new apps/updates that
 *     target anything lower than Android 15 (API 35).
 *  2. A real `release` signing config pointing at the upload keystore, so
 *     `assembleRelease` produces an APK that can be uploaded as-is instead of
 *     one signed with the throwaway debug key.
 *
 * Credentials are read from env vars when present, with the existing local
 * upload-key values as a fallback. Never commit the .keystore itself.
 */
const { withAppBuildGradle, withGradleProperties } = require('@expo/config-plugins');

const TARGET_SDK_PROPERTY = 'android.targetSdkVersion';
const TARGET_SDK = '35';

const KEYSTORE_PATH =
  'System.getProperty("user.home") + "/.android/my-release-key.keystore"';

function withTargetSdk(config) {
  return withGradleProperties(config, (configProps) => {
    const index = configProps.modResults.findIndex(
      (p) => p.type === 'property' && p.key === TARGET_SDK_PROPERTY
    );
    const entry = { type: 'property', key: TARGET_SDK_PROPERTY, value: TARGET_SDK };
    if (index >= 0) configProps.modResults[index] = entry;
    else configProps.modResults.push(entry);
    return configProps;
  });
}

function withReleaseSigning(config) {
  return withAppBuildGradle(config, (configProps) => {
    if (configProps.modResults.language !== 'groovy') return configProps;
    let contents = configProps.modResults.contents;

    if (!contents.includes('signingConfigs.release')) {
      const releaseBlock = `
        release {
            // Google Play upload key. Override with env vars on CI.
            storeFile file(${KEYSTORE_PATH})
            storePassword System.getenv("ZYVERSE_KEYSTORE_PASSWORD") ?: "yourstorepassword"
            keyAlias System.getenv("ZYVERSE_KEY_ALIAS") ?: "my-key-alias"
            keyPassword System.getenv("ZYVERSE_KEY_PASSWORD") ?: "yourstorepassword"
        }`;

      contents = contents.replace(/signingConfigs\s*\{/, (match) => `${match}${releaseBlock}`);
    }

    // Point the release build type at the upload key. Anchored on Expo's own
    // "Caution!" comment so the debug build type is left untouched.
    contents = contents.replace(
      /(\/\/ Caution! In production, you need to generate your own keystore file\.\s*\r?\n\s*\/\/ see https:\/\/reactnative\.dev\/docs\/signed-apk-android\.\s*\r?\n\s*)signingConfig signingConfigs\.debug/,
      '$1signingConfig signingConfigs.release'
    );

    configProps.modResults.contents = contents;
    return configProps;
  });
}

module.exports = function withZyniReleaseConfig(config) {
  return withReleaseSigning(withTargetSdk(config));
};
